  <script src='https://cdn.jsdelivr.net/npm/fullcalendar@6.1.15/index.global.min.js'></script>
  <script src="https://cdn.jsdelivr.net/npm/moment@2.30.1/moment.min.js"></script>
  <script>
    var castId = {{ $diary->cast->id }};
    var shopUrl = '{{ $diary->cast->shop->url }}';
    var archives = @json($archives);
    document.addEventListener('DOMContentLoaded', function() {
      var eventsAll = archives.map(archive => {
        const date = moment(archive.created_at).format('YYYY-MM-DD')
        return {
          start: date,
          end: date,
          url: `/touchvip/diary/${archive.slug}`
        }
      });
      var events = Array.from(
        new Map(eventsAll.map((event) => [event.start, event])).values()
      );
      var calendarEl = document.getElementById('calendar');
      var calendar = new FullCalendar.Calendar(calendarEl, {
        locale: 'ja',
        headerToolbar: {
          left: 'prev',
          center: 'title',
          right: 'next'
        },
        views: {
          dayGridMonth: {
            titleFormat: { year: 'numeric', month: 'numeric' }
          },
        },
        dayCellContent: (arg) => arg.date.getDate(),
        events: events,
      });
      calendar.render();

      var archivesEl = document.getElementById('archives');
      var archiveItems = archives.map(archive => moment(archive.created_at).format('YYYY-MM'));
      archiveItems = [...new Set(archiveItems)]
      archiveItems.forEach((archive, index) => {
        const url = `/touchvip/diary/${castId}/${archive}`
        const a = document.createElement('a')
        a.href = url
        a.textContent = moment(archive).format('YYYY年MM月')
        archivesEl.appendChild(a)
      });

      var castStatusApi = `${shopUrl}/wp-json/cast/${castId}`
      fetch(castStatusApi)
        .then(response => response.text())
        .then(data => {
          var castStatus = document.querySelectorAll('.diary-status');
          castStatus.forEach(status => {
            status.innerHTML = data || '<span class="machihime-icon icon_10" style="background-color:#666666">本日お休み</span>';
          });
        });
    });
  </script>
